// src/features/tasks/components/hold-to-delete.tsx
import { Gesture } from 'react-native-gesture-handler';

export const HOLD_TO_DELETE = Gesture.LongPress().minDuration(450);

// src/features/tasks/defer-work.ts
import { InteractionManager } from 'react-native';

export function deferWork(task: () => void): void {
  InteractionManager.runAfterInteractions(task);
}

// test/config-plugins/run-mod.ts
import type { ExportedConfig } from 'expo/config-plugins.js';
import { withPlugins } from 'expo/config-plugins.js';

export const runAll = (config: ExportedConfig): ExportedConfig => withPlugins(config, []);
